// Node 2: 生成爬取任务列表
// 每个 item 包含一个目的地 + 搜索关键词

const destinations = [
  { city: "东京", country: "日本", destination: "日本",
    keywords: ["东京citywalk攻略", "东京美食探店路线", "东京5日游行程"] },
  { city: "京都", country: "日本", destination: "日本",
    keywords: ["京都寺庙游览路线", "京都和服体验攻略"] },
  { city: "曼谷", country: "泰国", destination: "泰国",
    keywords: ["曼谷夜市美食攻略", "曼谷4日游行程"] },
  { city: "首尔", country: "韩国", destination: "韩国",
    keywords: ["首尔弘大citywalk", "首尔美食打卡路线"] },
  { city: "巴黎", country: "法国", destination: "法国",
    keywords: ["巴黎5日游攻略", "巴黎博物馆路线"] },
  { city: "纽约", country: "美国", destination: "美国",
    keywords: ["纽约自由行攻略", "纽约曼哈顿地区美食"] },
  { city: "新加坡", country: "新加坡", destination: "新加坡",
    keywords: ["新加坡3日精华游", "新加坡亲子游路线"] },
  { city: "巴厘岛", country: "印度尼西亚", destination: "印度尼西亚",
    keywords: ["巴厘岛度假路线", "巴厘岛乌布德攻略"] }
];

// 每次随机选 3 个目的地，每个取 1 个关键词
const shuffled = destinations.sort(() => Math.random() - 0.5).slice(0, 3);
const tasks = shuffled.map(d => ({
  json: {
    city: d.city,
    country: d.country,
    destination: d.destination,
    keyword: d.keywords[Math.floor(Math.random() * d.keywords.length)]
  }
}));

return tasks;

// Node 5: 解析 route 主信息
const raw = $input.first().json;
const content = raw.choices?.[0]?.message?.content || "";

// Clean markdown wrapper if present
const cleaned = content.replace(/```json/g, "").replace(/```/g, "").trim();

let data;
try {
  data = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    data = JSON.parse(match[0]);
  } else {
    throw new Error("Failed to parse AI response as JSON: " + cleaned.substring(0, 200));
  }
}

// Get city/destination from Node 2 task info
const taskInfo = $items("Function")[0]?.json || {};

return [{
  json: {
    route_title: data.route_title || taskInfo.keyword || "",
    city: data.city || taskInfo.city || "",
    country: data.country || taskInfo.country || "",
    destination: taskInfo.destination || data.country || "",
    route_theme: data.route_theme || "",
    mood: data.mood || "",
    places: JSON.stringify(data.days || []),
    summary: data.summary || "",
    raw_json: data,
    source_url: taskInfo.source_url || "",
    status: "published",
    quality_score: 85,
    target_user: data.travel_type || "",
    best_time: data.best_time || "",
    days_count: data.days_count || data.days?.length || null,
    budget_level: data.budget_level || "",
    travel_type: data.travel_type || "",
    pace: data.pace || "",
    tags: data.tags || "",
    cover_url: "",
    likes: 0
  }
}];

// Function1: 拆分 days
const routeId = $input.first().json.id;
const raw = $input.first().json.raw_json || {};
const days = raw.days || [];

if (!routeId) {
  throw new Error("No route_id returned from Postgres insert. Check Return Fields = *");
}

if (days.length === 0) {
  throw new Error("No days found in raw_json. AI response may be empty.");
}

return days.map((day, index) => ({
  json: {
    route_id: routeId,
    day_number: day.day || index + 1,
    title: day.title || "Day " + (index + 1),
    summary: day.summary || "",
    places: day.places || []
  }
}));

// Function2: 拆分 places
const dayId = $input.first().json.id;
const dayNumber = $input.first().json.day_number;

// Get places from Function1 output (which preserved them)
const function1Items = $items("Function1");
const matched = function1Items.find(
  item => String(item.json.day_number) === String(dayNumber)
);
const places = matched?.json?.places || [];

if (places.length === 0) {
  return [];
}

return places.map((place, index) => ({
  json: {
    day_id: dayId,
    place_name: place.name || place.place_name || "",
    visit_time: place.time || place.visit_time || "",
    duration_min: place.duration_min || null,
    description: place.description || "",
    intro: place.intro || "",
    category: place.category || "景点",
    rating: place.rating || null,
    price: place.price || "",
    tags: Array.isArray(place.tags) ? place.tags.join(",") : (place.tags || ""),
    place_order: index + 1,
    latitude: place.lat || null,
    longitude: place.lng || null,
    image_url: "",
    address: place.address || ""
  }
}));
